use vstd::prelude::*;

verus! {
    fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
        requires
            !a.is_empty(),
        ensures
            result.len() == a.len(),
            forall |i: usize| 0 <= i && i < a.len() ==> !result[i].is_empty(),
    {
        let mut result: Vec<Vec<String>> = Vec::new();
        let mut idx: usize = 0;

        while idx < a.len()
            invariant
                idx <= a.len(),
                result.len() == idx,
                forall |i: usize| 0 <= i && i < idx ==> !result[i].is_empty(),
        {
            // Here we would split the string a[idx] into lines based on the keepends flag.
            // For simplicity, let's assume we split by newlines and keepends is just a flag
            // that determines if we include the newline character in the resulting strings.

            let mut inner_list: Vec<String> = Vec::new();
            let lines: Vec<String> = a[idx].split('\n').map(|s| s.to_string()).collect();

            // If keepends is true, we would append the newline character to each line.
            for line in lines {
                if keepends {
                    inner_list.push(line + "\n");
                } else {
                    inner_list.push(line);
                }
            }

            // Ensure that inner_list is non-empty before adding to result
            assert(!inner_list.is_empty());
            result.push(inner_list);
            idx = idx + 1;
        }

        result
    }
}

